export default function TaskInterface({task, act}) {
  const t = task || {};
  const m = t.merchant || {};
  const intent = t.intent || {};
  const array = v => Array.isArray(v) ? v : [];
  const text = v => v == null ? 'Unknown' : typeof v === 'object' ? JSON.stringify(v) : String(v);
  const overview = !task || t.status === 'not_started';
  const busy = !!t.progress || ['working', 'created', 'submitting'].includes(t.status);
  const locked = overview || busy || !!t.receipt;
  const [localMethod, setLocalMethod] = React.useState(null);
  const [localReason, setLocalReason] = React.useState(null);
  const methods = array(m.methods).filter(v => ['print_label', 'qr_dropoff'].includes(v.value));
  const reasons = array(m.reasons).filter(v => v.value);
  const checks = array(t.checks);
  const lines = array(m.lines);
  const selected = Array.isArray(m.selectedLines) ? m.selectedLines.map(v => typeof v === 'object' && v ? v.id : v) : null;
  const method = localMethod === null ? (intent.method || m.method || '') : localMethod;
  const reason = localReason === null ? (t.reason || '') : localReason;
  const destination = intent.refundDestination || 'original_payment';
  const methodLabel = v => ({print_label:'Print a shipping label', qr_dropoff:'Printer-free QR drop-off'}[v]) || (methods.find(x => x.value === v) || {}).label || text(v);
  const destinationLabel = v => ({original_payment:'Original payment method', store_credit:'Store credit'}[v]) || (array(m.destinations).find(x => x.value === v) || {}).label || text(v);
  const money = v => {
    if (typeof v !== 'number' || !Number.isFinite(v) || !m.currency) return 'Unknown';
    try { return new Intl.NumberFormat('en-US', {style:'currency',currency:m.currency}).format(v / 100); }
    catch (_) { return String(v / 100) + ' ' + m.currency; }
  };
  const destinationConflict = m.refundDestination != null && m.refundDestination !== destination;
  const methodConflict = method && m.method && method !== m.method;
  const reasonConflict = reason && m.reason != null && reason !== m.reason;
  const itemConflict = selected !== null && lines.some(line => {
    const name = (text(line.name) + ' ' + text(line.id)).toLowerCase();
    return (name.includes('jacket') && selected.includes(line.id)) || (name.includes('red') && name.includes('shoe') && !selected.includes(line.id));
  });
  const conflict = t.status === 'conflict' || destinationConflict || methodConflict || reasonConflict || itemConflict || checks.some(c => ['conflict','failed','fail','mismatch','error'].includes(c.status));
  const unknown = m.deductionCents == null || m.expectedRefundCents == null || !m.currency || !m.method || !m.refundDestination || selected === null;
  const discovery = t.discovery || {};
  const screens = array(discovery.screens);
  const flows = array(discovery.flows);
  const detail = (methods.find(x => x.value === method) || {}).detail;
  const status = t.receipt ? 'A receipt is available. Consult the host’s separately verified result.' : busy ? 'Working. Waiting for the source check to finish; controls are locked.' : overview ? 'Overview only. No return has been submitted.' : conflict ? 'Source check complete: conflict. Submission is blocked; review requested and observed terms.' : t.error ? 'An error needs attention. No completion is claimed.' : 'Review the current source terms. Validation is not submission.';
  function chooseMethod(value) {
    if (locked) return;
    setLocalMethod(value);
    act('choice', {method:value});
  }
  function chooseReason(value) {
    if (locked) return;
    setLocalReason(value);
    act('choice', {reason:value});
  }
  function check(repair) {
    if (!locked) act('check', {repair});
  }
  return <main className="generated-root">
    <header className="generated-header">
      <p className="generated-eyebrow">Merchant sandbox · Synthetic records only</p>
      <h1>{overview ? 'Explore your return options' : 'Review your return'}</h1>
      <p className="generated-lead">Return only the red shoes. Keep the jacket. Refund original payment.</p>
    </header>
    <div className="generated-status" role="status" aria-live="polite" aria-atomic="true">{status}</div>
    {!overview && conflict && <section className="generated-conflict" aria-labelledby="generated-conflict-title">
      <p className="generated-eyebrow">Source conflict · Submission blocked</p>
      <h2 id="generated-conflict-title">Your choices and source do not match</h2>
      <p>Changing the return method can change the source refund destination. Your requested destination remains unchanged.</p>
      <div className="generated-comparison">
        <section><h3>Requested refund destination</h3><p className="generated-value">{destinationLabel(destination)}</p></section>
        <section><h3>Observed refund destination</h3><p className="generated-value">{destinationLabel(m.refundDestination)}</p></section>
      </div>
      <dl className="generated-summary">
        <div><dt>Observed return method</dt><dd>{methodLabel(m.method)}</dd></div>
        <div><dt>Method fee / deduction</dt><dd>{money(m.deductionCents)}</dd></div>
        <div><dt>Expected refund</dt><dd>{money(m.expectedRefundCents)}</dd></div>
      </dl>
      {methodConflict && <p>Requested return method: {methodLabel(method)}<br />Observed return method: {methodLabel(m.method)}</p>}
      {reasonConflict && <p>Requested return reason: {text(reason)}<br />Observed return reason: {text(m.reason)}</p>}
      {itemConflict && <p>Requested: return only red shoes; keep jacket.<br />Observed selected items: {selected.map(id => (lines.find(x => x.id === id) || {}).name || text(id)).join(', ') || 'None'}</p>}
      <p>Restore your choices, then review the refreshed terms. Restoring does not approve or submit a return.</p>
      <button type="button" disabled={locked} onClick={() => check(true)}>Restore my choices</button>
    </section>}
    {t.error && <section className="generated-error" role="alert"><h2>{conflict ? 'Source check message' : 'Unable to continue'}</h2><p>{text(t.error.message || t.error)}</p></section>}
    {overview ? <>
      <section className="generated-panel">
        <h2>Observed screens and flows</h2>
        {screens.length ? <ul className="generated-list">{screens.map((s,i) => <li key={s.id || i}><strong>{s.name || 'Observed screen'}</strong><p>{text(s.reachedState || s.stateLabel || 'Screen reached; completed return not verified.')}</p></li>)}</ul> : <p>Returns | Merchant sandbox — item choices, return method, refund destination, and draft review were observed.</p>}
        {flows.length > 0 && <div className="generated-grid">{flows.map((f,i) => <section className="generated-mini" key={f.id || i}><h3>{f.name || f.label || 'Discovered flow'}</h3><p>{text(f.reachedState || f.stateLabel || 'Reached-state evidence not supplied.')}</p><p className="generated-muted">Informational only; no execution from this card.</p></section>)}</div>}
        <p className="generated-muted">The initial read-only run blocked draft writes, limiting item and reason exploration. Later sandbox observations reached the draft states below. Neither branch verified a submitted return.</p>
      </section>
      <section className="generated-panel">
        <h2>Two observed method paths</h2>
        <div className="generated-grid">
          <section className="generated-mini"><p className="generated-tag">Reached: saved draft review</p><h3>Print a shipping label</h3><p>Only the red shoes were selected; the jacket was kept. The source destination was Original payment method.</p><p>Print and attach the label, then drop off the parcel.</p><p className="generated-muted">Draft only — submission and confirmation not verified.</p></section>
          <section className="generated-mini"><p className="generated-tag">Reached: saved draft with destination mismatch</p><h3>Printer-free QR drop-off</h3><p>Only the red shoes were selected; the jacket was kept. Changing to QR drop-off changed the source destination to Store credit despite the original-payment selection.</p><p>A drop-off fee was observed. A QR code is shown at the counter.</p><p className="generated-muted">Draft only — submission and confirmation not verified.</p></section>
        </div>
        <p className="generated-note">Method changes may change the refund destination. Current task data supplies the fee, refund, and destination after you start; historical observations are not current quotes.</p>
      </section>
      <section className="generated-panel"><h2>Supported task</h2><p>Return the red shoes, keep the jacket, refund original payment.</p><p>Use the host’s “Start this task” control to begin this specific task. Starting is not approval to submit.</p></section>
    </> : <>
      <div className="generated-layout">
        <div>
          <section className="generated-panel">
            <p className="generated-eyebrow">01 · Items</p><h2>Return shoes · Keep jacket</h2>
            <p>Your item instructions are fixed. The jacket is not offered for return.</p>
            {lines.length ? <ul className="generated-list">{lines.map((line,i) => <li key={line.id || i}><strong>{line.name || 'Unnamed source item'}</strong>{line.variant && <p>{text(line.variant)}</p>}<p className="generated-muted">Observed source: {selected === null ? 'selection unknown' : selected.includes(line.id) ? 'selected for return' : 'not selected for return'}</p></li>)}</ul> : <p>Source items: Unknown</p>}
          </section>
          <section className="generated-panel">
            <p className="generated-eyebrow">02 · Requested choices</p><h2>How to handle the return</h2>
            <label className="generated-label" htmlFor="generated-reason">Return reason</label>
            <select id="generated-reason" value={reason} disabled={locked || !reasons.length} onChange={e => chooseReason(e.target.value)}>
              <option value="">Choose a reason</option>
              {reason && !reasons.some(x => x.value === reason) && <option value={reason}>{text(reason)}</option>}
              {reasons.map(x => <option key={x.value} value={x.value}>{x.label || x.value}</option>)}
            </select>
            {!reasons.length && <p className="generated-muted">Available reasons are unknown.</p>}
            <label className="generated-label" htmlFor="generated-method">Return method</label>
            <select id="generated-method" value={method} disabled={locked || !methods.length} aria-describedby="generated-method-note" onChange={e => chooseMethod(e.target.value)}>
              <option value="">Choose a method</option>
              {method && !methods.some(x => x.value === method) && <option value={method}>{methodLabel(method)}</option>}
              {methods.map(x => <option key={x.value} value={x.value}>{x.label || methodLabel(x.value)}</option>)}
            </select>
            {!methods.length && <p className="generated-muted">Available methods are unknown.</p>}
            <p id="generated-method-note" className="generated-note">Changing the method may change the source refund destination. Your original-payment preference stays unchanged. Review the refreshed source terms for conflicts.</p>
            {detail && <p>{text(detail)}</p>}
            {intent.noPrinter && <p className="generated-note">Your preference: no printer.</p>}
            <h3>Requested refund destination</h3><p>{destinationLabel(destination)}</p>
          </section>
        </div>
        <section className="generated-panel generated-review">
          <p className="generated-eyebrow">03 · Source review</p><h2>Current observed terms</h2>
          <p className="generated-muted">These source values are separate from your requested choices.{busy ? ' Refresh in progress; these may be prior values.' : ''}</p>
          <dl className="generated-terms">
            <div><dt>Return method</dt><dd>{methodLabel(m.method)}</dd></div>
            <div><dt>Method fee / deduction</dt><dd>{money(m.deductionCents)}</dd></div>
            <div><dt>Refund destination</dt><dd>{destinationLabel(m.refundDestination)}</dd></div>
            <div><dt>Requested refund destination</dt><dd>{destinationLabel(destination)}</dd></div>
            <div className="generated-total"><dt>Expected refund</dt><dd>{money(m.expectedRefundCents)}</dd></div>
          </dl>
          {unknown && <p className="generated-note">Some source terms are unknown. Validate to inspect them. Unknown terms must be resolved before approval.</p>}
          <button type="button" className="generated-primary" disabled={locked} onClick={() => check(false)}>Validate current terms</button>
          <p className="generated-muted">Validation is not submission. The host handles exact approval, submission, and separately verified saved confirmation.</p>
        </section>
      </div>
      {checks.length > 0 && <section className="generated-panel"><h2>Source check details</h2><ul className="generated-list">{checks.map((c,i) => <li key={c.key || i}><div className="generated-check-heading"><strong>{c.label || 'Source check'}</strong><span>{text(c.status)}</span></div><p>Expected: {text(c.expected)}<br />Observed: {text(c.observed)}</p></li>)}</ul></section>}
    </>}
    <footer className="generated-footer">Sandbox only · No production access. A saved draft is not a completed return.</footer>
  </main>;
}
